// sel-extru-un-clic v1
// Parche: si con la herramienta Seleccionar se ha fijado la esquina A (un solo
// clic) pero AÚN NO la B, Ctrl+rueda auto-confirma la caja usando como B el
// bloque apuntado (la misma caja que se ve en el preview cian) y extruye
// directamente, sin necesitar el segundo clic.
//
// API:
//   game.selExtruUnClic.on()      activa
//   game.selExtruUnClic.off()     restaura
//   game.selExtruUnClic.estado()  info
//
(() => {
'use strict';

let activo = false;
let handler = null;

function onWheel(e){
  if(!mc.active || document.pointerLockElement !== mc.canvas) return;
  if(!e.ctrlKey || mc.tool !== 'select') return;
  // Solo actúa si hay esquina A sin confirmar y NO hay caja ya hecha
  if(!mc.selA || mc.selBox) return;
  // Esquina B = el bloque apuntado (lo mismo que dibuja el preview cian)
  const near = mcRaycast();
  const b = (near && near.cell[1] >= 0) ? near.cell.slice() : mc.selA.slice();
  // Auto-confirmar la caja
  const caja = { a: mc.selA.slice(), b: b };
  if(mc.selSuma) mc.selCajas.push(caja); else mc.selBox = caja;
  mc.selA = null; mc.selSuma = false;
  const n = mcSelCount();
  toast(n + ' bloque(s) — auto-selección · Ctrl+rueda extruye/cava');
  // El evento sigue burbujeando hasta el handler original del wheel
  // que ya ve mc.selBox y extruye.
}

function instalar(){
  handler = onWheel;
  window.addEventListener('wheel', handler, { capture: true, passive: false });
  activo = true;
}

function desinstalar(){
  if(handler) window.removeEventListener('wheel', handler, { capture: true });
  handler = null;
  activo = false;
}

function estado(){
  const s = 'sel-extru-un-clic: ' + (activo ? 'ACTIVO' : 'inactivo');
  console.log(s);
  return s;
}

const API = {
  on(){ if(!activo) instalar(); return 'sel-extru-un-clic activado'; },
  off(){ if(activo) desinstalar(); return 'sel-extru-un-clic desactivado'; },
  estado
};
game.selExtruUnClic = API;
API.on();
})();
